SELECT        ITP_INFORMECHECKLISTGHK.IdInformeCheckList, ITP_CHECKLISTGHK.Pregunta, ITP_RESPUESTACHECKLISTGHK.IdRespGHK, ITP_CHECKLISTGHK.NumPregunta, ITP_RESPUESTACHECKLISTGHK.RespuestaBien, 
                         ITP_RESPUESTACHECKLISTGHK.RespuestaMal, ITP_RESPUESTACHECKLISTGHK.RespuestaNA, ITP_RESPUESTACHECKLISTGHK.AnomaliasDetectadas, ITP_RESPUESTACHECKLISTGHK.Accion, 
                         FORMAT(ITP_INFORMECHECKLISTGHK.Fecha, 'dd/MM/yyyy HH:mm:ss') AS Fecha
FROM            ITP_RESPUESTACHECKLISTGHK full JOIN
                         ITP_CHECKLISTGHK ON ITP_RESPUESTACHECKLISTGHK.IdPregunta = ITP_CHECKLISTGHK.IdPregunta full JOIN
                         ITP_INFORMECHECKLISTGHK ON ITP_RESPUESTACHECKLISTGHK.IdInformeCheckList = ITP_INFORMECHECKLISTGHK.IdInformeCheckList
                         order by IdInformeCheckList, NumPregunta asc